# Double-check by looking for any edge that has 32bb90e897 as the target
# and also verify we parsed correctly by checking outgoing edges from 32bb90e897

outgoing = []
for line in edges_text.split('\n'):
    line = line.strip()
    if '->' in line:
        parts = line.split('->')
        source = parts[0].strip()
        target = parts[1].strip()
        if source == '32bb90e897':
            outgoing.append(target)

print("Outgoing edges from 32bb90e897:", outgoing)
print("\nSearching for '32bb90e897' in all edges as target...")
found_as_target = False
for line in edges_text.split('\n'):
    if '32bb90e897' in line and '->' in line:
        parts = line.split('->')
        target = parts[1].strip()
        if target == '32bb90e897':
            found_as_target = True
            print(f"Found as target: {line}")

if not found_as_target:
